from src.black.ranges import parse_line_ranges

def test_parse_line_ranges():
    # Valid ranges
    assert parse_line_ranges(["1-5"]) == [(1, 5)]
    assert parse_line_ranges(["5-5"]) == [(5, 5)]
    assert parse_line_ranges(["1-5", "10-15"]) == [(1, 5), (10, 15)]

    # Invalid ranges - Reversed
    try:
        parse_line_ranges(["5-3"])
        print("Failed: 5-3 should have raised ValueError")
    except ValueError as e:
        print(f"Passed: 5-3 raised {e}")

    # Invalid ranges - Zero
    try:
        parse_line_ranges(["0-5"])
        print("Failed: 0-5 should have raised ValueError")
    except ValueError as e:
        print(f"Passed: 0-5 raised {e}")

    # Invalid ranges - Negative
    try:
        parse_line_ranges(["-1-5"])
        print("Failed: -1-5 should have raised ValueError")
    except ValueError as e:
        print(f"Passed: -1-5 raised {e}")

    # Invalid ranges - Negative end
    try:
        parse_line_ranges(["1--1"])
        print("Failed: 1--1 should have raised ValueError")
    except ValueError as e:
        print(f"Passed: 1--1 raised {e}")

if __name__ == "__main__":
    test_parse_line_ranges()

